# owner: platform
"""Short text notices for parents about missed days."""

from typing import Iterable, List

from rosterkit.attendance import days_missed
from rosterkit.models import Mark, Student

class NoticeError(ValueError):
    """The marks cannot be turned into a notice."""

def _check_owner(student: Student, marks: List[Mark]):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise NoticeError(
                f"mark for {mark.student_id} given "
                f"with student {student.student_id}"
            )

def _headline(student: Student, count: int) -> str:
    noun = "day" if count == 1 else "days"
    name = f"{student.first_name} {student.last_name}"
    return f"{name} missed {count} {noun} of school:"

def _bullets(dates: list) -> str:
    return "\n".join(
        f"- {when.isoformat()}" for when in dates
    )

def _compose(student: Student, dates: list) -> str:
    return (
        "Dear parent or guardian,\n\n"
        f"{_headline(student, len(dates))}\n"
        f"{_bullets(dates)}\n"
    )

def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Build a notice listing absent days, oldest first."""
    marks = list(marks)
    _check_owner(student, marks)
    dates = days_missed(marks)
    if not dates:
        raise NoticeError(
            f"no absences for {student.student_id}"
        )
    return _compose(student, dates)
